    def next_month_days(month_idx):
        # Days in months for a non-leap year: 
        # Jan=31, Feb=28, Mar=31, Apr=30, May=31, Jun=30, Jul=31, Aug=31, Sep=30, Oct=31, Nov=30, Dec=31
        months_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
