import sys

def solve():
    days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]

    def get_index(name):
        return days.index(name)

    def get_offset(month):
        # Days in each month for a non-leap year
        # Index 0 -> January, 1 -> February, ..., 11 -> December
        offsets = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return offsets[month]

    input_days = sys.stdin.read().strip().split()
    if len(input_days) != 2:
        return

    day1_name, day2_name = input_days
    d1 = get_index(day1_name)
    d2 = get_index(day2_name)

    # There are 11 possible transitions between consecutive months in a year
    # We check if there exists any month m (0 to 10) such that:
    # (day_of_week_of_month_m + days_in_month_m) % 7 == day_of_week_of_month_(m+1)
    # which translates to:
    # (d1 + days_in_month_m) % 7 == d2

    possible = False
    for m in range(11):
        offset = get_offset(m)
        if (d1 + offset) % 7 == d2:
            possible = True
            break

    if possible:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()

